            pat.append(bottom[c])
            c += 1
        patterns.append(pat)

    lookup = {}
    for pat in patterns:
        for i, color in enumerate(pat):
            lookup[color] = (pat, i)

    seen = set()
    for r in range(h - 1):
        for c in range(w):
            if not grid[r][c] or (r, c) in seen:
                continue
            # Find each connected nonzero object; only singleton objects are anchors.
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h - 1 and 0 <= nx < w
                            and grid[ny][nx] != 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if len(cells) != 1:
                continue
            y, x = cells[0]
            color = grid[y][x]
            if color not in lookup:
                continue
            pat, i = lookup[color]
            start = x - i
            for j, value in enumerate(pat):
                xx = start + j
                if 0 <= xx < w:
                    out[y][xx] = value
    return out
